    "id": "CP-006",
    "module": "CP",
    "moduleName": "7. Jetpack Compose & Deklarativ UI",
    "moduleOrder": 7,
    "title": "6-dars. Side-effect'lar: LaunchedEffect, DisposableEffect va derivedStateOf",
    "shortTitle": "6. Side-effect",
    "summary": "Bu darsdan keyin composable'dan so'rov, navigatsiya yoki listener'ni qanday to'g'ri ishga tushirishni bilasiz.",
    "origin": "Mavjud qo‘llanmadan",
    "priority": 2,
    "minutes": 35,
